mapper.select:
SELECT DISTINCT s.* FROM student s LEFT JOIN stu_region sr ON s.id = sr.stu_id LEFT JOIN stu_language sl ON s.id = sl.stu_id LEFT JOIN stu_certificate sc ON s.id = sc.stu_id LEFT JOIN stu_internship si ON s.id = si.stu_id LEFT JOIN stu_speciality ss ON s.id = ss.stu_id
AND s.id = #{query.id}
AND s.stu_id = #{query.stuId}
AND s.name LIKE CONCAT('%', #{query.name}, '%')
AND s.age = #{query.age}
AND s.gender = #{query.gender}
AND s.nation LIKE CONCAT('%', #{query.nation}, '%')
AND s.major LIKE CONCAT('%', #{query.major}, '%')
AND s.degree = #{query.degree}
AND s.graduation_year >= #{query.graduationYear}
AND s.internship >= #{query.internship}
AND sr.city LIKE CONCAT('%', #{query.city}, '%')
AND sr.province LIKE CONCAT('%', #{query.province}, '%')
AND sl.language LIKE CONCAT('%', #{query.language}, '%')
AND sl.level LIKE CONCAT('%', #{query.languageLevel}, '%')
AND sc.cert_name LIKE CONCAT('%', #{query.certName}, '%')
AND sc.level LIKE CONCAT('%', #{query.certLevel}, '%')
AND si.company LIKE CONCAT('%', #{query.internshipCompany}, '%')
AND ss.speciality LIKE CONCAT('%', #{query.speciality}, '%')
ORDER BY s.id
